function QuickSDKCallBack:OnFbSharePhoto(errorReason, status)
    --CommonHelper:PlayScreenEffectWaiting(false)
    --CommonTipsHelper:ShowCenterTips(errorReason)
    -- 图片0  1  2    url   3  4  5
    QuickTaHelper:Get():ShareEvent('OnFbShareCallBack',status)
    --log(" lua OnFbShare  status: "..status)
    if status == "0" then
        --CommonTipsHelper:ShowCenterTips("分享图片成功");
        --这块可以请求服务器发奖啥的
        local recruitData = RecruitDataManager:Get():GetDataById(701)--指定查找的活动id
        if recruitData.info.curShare == 0 then
            RecruitSubsystem:Get():SendMsg_Share(701)
        end
    elseif status == "1" then
        --CommonTipsHelper:ShowCenterTips("分享图片失败" .. errorReason);
    elseif status == "2" then
        --CommonTipsHelper:ShowCenterTips("取消了图片分享");
    elseif status == "3" then
        --CommonTipsHelper:ShowCenterTips("分享URL成功");
        --这块可以请求服务器发奖啥的
    elseif status == "4" then
        --CommonTipsHelper:ShowCenterTips("分享URL失败" .. errorReason);
    elseif status == "5" then
        --CommonTipsHelper:ShowCenterTips("取消了URL分享");
    end
end

